def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-width and full-height separator lines.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep = grid[r][0]
            break
    if sep is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1:
                sep = vals[0]
                break

    row_lines = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_lines = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    row_bounds = [-1] + row_lines + [h]
    col_bounds = [-1] + col_lines + [w]

    colors = [v for row in grid for v in row if v != sep]
    from collections import Counter
    counts = Counter(colors)
    marker = max(counts, key=counts.get)
    background = next((v for v in colors if v != marker), marker)

    out = []
    for i in range(len(row_bounds) - 1):
        row = []
        for j in range(len(col_bounds) - 1):
            cells = [
                grid[r][c]
                for r in range(row_bounds[i] + 1, row_bounds[i + 1])
                for c in range(col_bounds[j] + 1, col_bounds[j + 1])
            ]
            row.append(1 if cells.count(marker) == 2 else background)
        out.append(row)
    return out
